AUDIT = []
POLICY = {("ana", "payroll.csv"): {"read"},
          ("bo", "payroll.csv"): {"read", "write"}}

def reference_monitor(subject, obj, mode):
    allowed = mode in POLICY.get((subject, obj), set())
    AUDIT.append((subject, obj, mode, "allow" if allowed else "deny"))
    return allowed

def open_file(subject, name, mode):
    if not reference_monitor(subject, name, mode):
        raise PermissionError(f"{subject} may not {mode} {name}")
    return f"handle:{name}:{mode}"

for who, mode in [("ana", "read"), ("ana", "write"), ("eve", "read")]:
    try:
        print(open_file(who, "payroll.csv", mode))
    except PermissionError as e:
        print("denied:", e)
print(len(AUDIT), "decisions logged; last:", AUDIT[-1])

# Output:
# handle:payroll.csv:read
# denied: ana may not write payroll.csv
# denied: eve may not read payroll.csv
# 3 decisions logged; last: ('eve', 'payroll.csv', 'read', 'deny')

LEVEL = {"UNCLASSIFIED": 0, "CONFIDENTIAL": 1, "SECRET": 2, "TOP SECRET": 3}

def dominates(a, b):
    """a dominates b: level at least as high AND every category of b."""
    return LEVEL[a[0]] >= LEVEL[b[0]] and set(b[1]) <= set(a[1])

def can_read(subject, obj):   # simple security property: no read up
    return dominates(subject, obj)

def can_write(subject, obj):  # *-property: no write down
    return dominates(obj, subject)

analyst = ("SECRET", {"NUCLEAR"})
files = {
    "memo":     ("CONFIDENTIAL", set()),
    "warplan":  ("TOP SECRET", {"NUCLEAR"}),
    "keys":     ("SECRET", {"CRYPTO"}),
    "bowling":  ("UNCLASSIFIED", set()),
    "summary":  ("SECRET", {"NUCLEAR"}),
}
for name, label in files.items():
    print(f"{name:8} read={can_read(analyst, label)!s:5} write={can_write(analyst, label)}")

# Output:
# memo     read=True  write=False
# warplan  read=False write=True
# keys     read=False write=False
# bowling  read=True  write=False
# summary  read=True  write=True

